import { type ReactNode, useMemo, useState } from 'react';
import { QueryClient, QueryClientProvider, useQueryClient } from '@tanstack/react-query';
import { Link, Route, Switch, useLocation } from 'wouter';
import {
  ArrowRight, Bell, BookOpen, CalendarDays, Check, ChevronRight, CircleHelp, Clock3, Compass,
  Download, ExternalLink, HeartHandshake, Home, LockKeyhole, MapPin, Menu, MessageCircle,
  Navigation, Pencil, Phone, Plus, Search, Settings, Shield, ShieldCheck, Sparkles, Star, Trash2, UserRound,
  UsersRound, X, Zap
} from 'lucide-react';
import {
  getGetHavenDashboardQueryKey, getListJournalEntriesQueryKey, getListJourneysQueryKey,
  getListTrustedContactsQueryKey, useCreateJourney, useCreateJournalEntry, useCreateSafetyCheckin, useCreateTrustedContact,
  useDeleteJournalEntry, useDeleteTrustedContact, useGetHavenDashboard, useListJournalEntries, useListJourneys,
  useListSupportResources, useListTrustedContacts, useSendCompanionMessage, useUpdateJournalEntry, useUpdateJourneyStatus
} from '@workspace/api-client-react';
import { ErrorBoundary } from '@/components/error-boundary';
import { Toaster } from '@/components/ui/toaster';
import { TooltipProvider } from '@/components/ui/tooltip';
import NotFound from '@/pages/not-found';

const queryClient = new QueryClient();

const moodLabels: Record<string, string> = { calm: 'Calm', happy: 'Bright', anxious: 'Uneasy', sad: 'Low', angry: 'Frustrated', overwhelmed: 'Full', numb: 'Numb' };
const moodDots: Record<string, string> = { calm: 'bg-[#668f82]', happy: 'bg-[#d5ae4c]', anxious: 'bg-[#c87967]', sad: 'bg-[#7897a3]', angry: 'bg-[#ae5a53]', overwhelmed: 'bg-[#aa8e55]', numb: 'bg-[#8f8e9b]' };
const dateLabel = (date?: string) => date ? new Intl.DateTimeFormat('en', { month: 'short', day: 'numeric' }).format(new Date(date)) : 'Recently';

function Logo({ compact = false }: { compact?: boolean }) {
  return <Link href="/" className="flex items-center gap-3" data-testid="link-logo">
    <span className="grid size-9 place-items-center rounded-[13px] bg-secondary text-primary shadow-sm"><ShieldCheck size={20} strokeWidth={2.4} /></span>
    {!compact && <span className="font-display text-[26px] leading-none tracking-tight">haven</span>}
  </Link>;
}

function Button({ children, variant = 'primary', className = '', ...props }: { children: ReactNode; variant?: 'primary' | 'soft' | 'quiet' | 'danger'; className?: string } & React.ButtonHTMLAttributes<HTMLButtonElement>) {
  const styles = { primary: 'bg-primary text-primary-foreground hover:translate-y-[-1px] hover:shadow-md', soft: 'bg-secondary text-secondary-foreground hover:brightness-[.98]', quiet: 'bg-transparent text-foreground hover:bg-muted', danger: 'bg-destructive text-destructive-foreground hover:brightness-95' };
  return <button className={`inline-flex min-h-10 items-center justify-center gap-2 rounded-full px-4 text-sm font-semibold transition-all disabled:cursor-not-allowed disabled:opacity-50 ${styles[variant]} ${className}`} {...props}>{children}</button>;
}
function Card({ children, className = '', ...props }: { children: ReactNode; className?: string } & React.HTMLAttributes<HTMLDivElement>) {
  return <section className={`rounded-[24px] border border-border bg-card shadow-sm ${className}`} {...props}>{children}</section>;
}
function Eyebrow({ children }: { children: ReactNode }) { return <p className="font-mono-ui text-[10px] font-bold uppercase tracking-[.18em] text-muted-foreground">{children}</p>; }
function LoadingState({ label = 'Finding your quiet space…' }: { label?: string }) { return <div className="space-y-4" aria-label="Loading"><div className="h-20 animate-pulse rounded-2xl bg-muted" /><div className="h-28 animate-pulse rounded-2xl bg-muted" /><p className="text-sm text-muted-foreground">{label}</p></div>; }
function ErrorState({ retry }: { retry?: () => void }) { return <Card className="p-6"><div className="flex items-start gap-4"><CircleHelp className="mt-1 text-accent" /><div><h3 className="font-semibold">This space is taking a moment</h3><p className="mt-1 text-sm text-muted-foreground">Haven could not connect right now. Your private space has not changed.</p>{retry && <Button variant="soft" className="mt-4" onClick={retry} data-testid="button-retry">Try again</Button>}</div></div></Card>; }
function EmptyState({ icon: Icon = HeartHandshake, title, detail, action }: { icon?: typeof HeartHandshake; title: string; detail: string; action?: ReactNode }) { return <div className="rounded-[22px] border border-dashed border-border bg-background/50 px-6 py-10 text-center"><span className="mx-auto grid size-12 place-items-center rounded-2xl bg-secondary/55 text-primary"><Icon size={22} /></span><h3 className="mt-4 font-display text-2xl">{title}</h3><p className="mx-auto mt-1 max-w-sm text-sm leading-6 text-muted-foreground">{detail}</p>{action && <div className="mt-5">{action}</div>}</div>; }
function Field({ label, ...props }: { label: string } & React.InputHTMLAttributes<HTMLInputElement>) { return <label className="block text-sm font-semibold">{label}<input className="mt-2 h-11 w-full rounded-xl border border-input bg-background px-3 text-sm font-normal outline-none transition focus:border-primary" {...props} /></label>; }
function Textarea({ label, ...props }: { label: string } & React.TextareaHTMLAttributes<HTMLTextAreaElement>) { return <label className="block text-sm font-semibold">{label}<textarea className="mt-2 min-h-32 w-full resize-y rounded-xl border border-input bg-background p-3 text-sm font-normal outline-none transition focus:border-primary" {...props} /></label>; }

function Shell({ children }: { children: ReactNode }) {
  const [location] = useLocation();
  const [open, setOpen] = useState(false);
  const nav = [{ href: '/', label: 'Today', icon: Home }, { href: '/safety', label: 'Safety', icon: Shield }, { href: '/journal', label: 'Journal', icon: BookOpen }, { href: '/support', label: 'Support', icon: HeartHandshake }];
  return <div className="min-h-[100dvh] bg-background">
    <aside className={`fixed inset-y-0 left-0 z-40 w-[268px] border-r border-sidebar-border bg-sidebar px-5 py-6 text-sidebar-foreground transition-transform md:translate-x-0 ${open ? 'translate-x-0' : '-translate-x-full'}`}>
      <div className="flex items-center justify-between"><Logo /><button onClick={() => setOpen(false)} className="rounded-full p-2 md:hidden" data-testid="button-close-menu"><X size={18} /></button></div>
      <div className="mt-14"><Eyebrow>your quiet space</Eyebrow><nav className="mt-4 space-y-1">{nav.map(({ href, label, icon: Icon }) => <Link key={href} href={href} onClick={() => setOpen(false)} data-testid={`link-nav-${label.toLowerCase()}`} className={`flex items-center gap-3 rounded-2xl px-3 py-3 text-sm transition ${location === href ? 'bg-sidebar-accent text-sidebar-accent-foreground' : 'text-sidebar-foreground/70 hover:bg-sidebar-accent/70 hover:text-sidebar-foreground'}`}><Icon size={18} /><span>{label}</span>{location === href && <span className="ml-auto size-1.5 rounded-full bg-secondary" />}</Link>)}</nav></div>
      <div className="mt-10 border-t border-sidebar-border pt-8"><Eyebrow>keep close</Eyebrow><div className="mt-3 space-y-1"><Link href="/profile" className="flex items-center gap-3 rounded-2xl px-3 py-3 text-sm text-sidebar-foreground/70 hover:bg-sidebar-accent" data-testid="link-nav-profile"><Settings size={18} />Preferences</Link><Link href="/emergency" className="flex items-center gap-3 rounded-2xl px-3 py-3 text-sm text-sidebar-foreground/70 hover:bg-sidebar-accent" data-testid="link-nav-emergency"><Zap size={18} />Emergency support</Link></div></div>
      <div className="absolute bottom-6 left-5 right-5 rounded-2xl border border-sidebar-border bg-sidebar-accent p-4"><div className="flex items-center gap-2 text-secondary"><LockKeyhole size={14} /><span className="font-mono-ui text-[10px] uppercase tracking-wider">private by design</span></div><p className="mt-2 text-xs leading-5 text-sidebar-foreground/65">Haven only shares what you choose, when you choose it.</p></div>
    </aside>
    {open && <button className="fixed inset-0 z-30 bg-primary/20 md:hidden" onClick={() => setOpen(false)} aria-label="Close menu" data-testid="button-overlay" />}
    <main className="md:pl-[268px]"><header className="sticky top-0 z-20 flex h-[72px] items-center justify-between border-b border-border/70 bg-background/85 px-5 backdrop-blur-md md:px-10"><button className="rounded-full p-2 md:hidden" onClick={() => setOpen(true)} data-testid="button-open-menu"><Menu size={21} /></button><div className="md:hidden"><Logo compact /></div><div className="hidden md:block"><p className="text-xs text-muted-foreground">A softer place to land</p></div><div className="flex items-center gap-2"><Link href="/profile" className="grid size-9 place-items-center rounded-full border border-border bg-card text-primary" data-testid="link-header-profile"><UserRound size={17} /></Link></div></header><div className="mx-auto max-w-[1240px] px-5 py-8 md:px-10 md:py-12">{children}</div></main>
    <nav className="safe-area-bottom fixed bottom-0 left-0 right-0 z-20 flex items-center justify-around border-t border-border bg-card/95 px-2 pt-2 backdrop-blur-md md:hidden">{nav.map(({ href, label, icon: Icon }) => <Link key={href} href={href} data-testid={`link-mobile-${label.toLowerCase()}`} className={`flex min-w-[64px] flex-col items-center gap-1 rounded-xl px-3 py-1 text-[10px] ${location === href ? 'text-primary' : 'text-muted-foreground'}`}><Icon size={19} /><span>{label}</span></Link>)}</nav>
  </div>;
}

function PageHeading({ eyebrow, title, detail, action }: { eyebrow: string; title: string; detail?: string; action?: ReactNode }) { return <div className="mb-8 flex flex-col justify-between gap-5 md:flex-row md:items-end"><div><Eyebrow>{eyebrow}</Eyebrow><h1 className="mt-2 font-display text-5xl leading-[.95] tracking-tight text-primary md:text-6xl">{title}</h1>{detail && <p className="mt-3 max-w-xl text-sm leading-6 text-muted-foreground">{detail}</p>}</div>{action}</div>; }

function Dashboard() {
  const qc = useQueryClient();
  const [, setLocation] = useLocation();
  const dashboard = useGetHavenDashboard();
  const contacts = useListTrustedContacts();
  const checkin = useCreateSafetyCheckin({ mutation: { onSuccess: () => qc.invalidateQueries({ queryKey: getGetHavenDashboardQueryKey() }) } });
  const [mood, setMood] = useState<string | null>(null);
  const d = dashboard.data;
  const current = mood ?? d?.currentMood ?? 'safe';
  if (dashboard.isLoading) return <LoadingState />;
  if (dashboard.isError) return <ErrorState retry={() => dashboard.refetch()} />;
  const first = d?.firstName || 'there';
  return <div className="animate-rise space-y-6">
    <div className="flex flex-col justify-between gap-5 md:flex-row md:items-end"><div><Eyebrow>{new Intl.DateTimeFormat('en', { weekday: 'long', month: 'long', day: 'numeric' }).format(new Date())}</Eyebrow><h1 className="mt-2 font-display text-5xl leading-[.92] tracking-tight text-primary md:text-7xl">Good to see you,<br /><i>{first}.</i></h1><p className="mt-4 text-sm text-muted-foreground">Check in with yourself. Take what you need.</p></div><Button variant="quiet" className="self-start border border-border md:self-auto" onClick={() => setMood(null)} data-testid="button-reset-checkin"><span className="size-2 rounded-full bg-secondary" />Quiet mode on</Button></div>
    <div className="grid gap-5 lg:grid-cols-[1.35fr_.65fr]">
      <Card className="relative overflow-hidden bg-primary p-6 text-primary-foreground md:p-9"><div className="absolute -right-12 -top-16 size-64 rounded-full border border-secondary/20" /><div className="absolute -right-2 -top-6 size-44 rounded-full border border-secondary/20" /><div className="relative"><div className="flex items-center justify-between"><Eyebrow>right now</Eyebrow><span className="rounded-full bg-secondary/15 px-3 py-1 font-mono-ui text-[10px] uppercase tracking-widest text-secondary">private</span></div><h2 className="mt-8 max-w-md font-display text-4xl leading-none md:text-5xl">How is your inner weather?</h2><p className="mt-3 max-w-sm text-sm leading-6 text-primary-foreground/70">No right answer. A small check-in can make room for what comes next.</p><div className="mt-8 flex flex-wrap gap-2">{[['safe','Steady'],['uneasy','Uneasy'],['need_help','I need support']].map(([value,label]) => <button key={value} onClick={() => setMood(value)} data-testid={`button-mood-${value}`} className={`rounded-full border px-4 py-2.5 text-sm transition ${current === value ? 'border-secondary bg-secondary text-primary' : 'border-primary-foreground/20 text-primary-foreground/75 hover:border-secondary/60'}`}>{label}</button>)}</div>{mood && <div className="mt-5 flex items-center gap-2 text-sm text-secondary animate-rise"><Check size={16} />Noted. You can change this anytime.</div>}</div></Card>
      <Card className="flex flex-col justify-between bg-[#e6d7bd] p-6 text-primary"><div><div className="flex items-center justify-between"><span className="grid size-10 place-items-center rounded-2xl bg-[#f3e9d7]"><Compass size={19} /></span><span className="font-mono-ui text-[10px] uppercase tracking-widest text-primary/55">journey</span></div><h2 className="mt-8 font-display text-3xl leading-none">{d?.journey ? d.journey.destination : 'Going somewhere?'}</h2><p className="mt-2 text-sm leading-6 text-primary/65">{d?.journey ? `Expected by ${dateLabel(d.journey.expectedArrival)} · ${d.journey.sharingStatus === 'active' ? 'sharing on' : 'sharing unavailable'}` : 'Let someone you trust know your plan.'}</p></div><Link href="/safety" className="mt-8 flex items-center justify-between rounded-xl border border-primary/15 px-3 py-3 text-sm font-semibold hover:bg-[#f0e4d0]" data-testid="link-journey-card"><span>{d?.journey ? 'View journey' : 'Plan a journey'}</span><ArrowRight size={16} /></Link></Card>
    </div>
    <div className="grid gap-5 lg:grid-cols-[.78fr_1.22fr]">
      <Card className="p-6"><div className="flex items-center justify-between"><div><Eyebrow>your circle</Eyebrow><h2 className="mt-2 font-display text-3xl">Close by.</h2></div><span className="grid size-11 place-items-center rounded-2xl bg-secondary text-primary"><UsersRound size={20} /></span></div><div className="mt-7 flex items-end gap-2"><span className="font-display text-5xl text-primary">{d?.trustedContactCount ?? contacts.data?.length ?? 0}</span><span className="pb-2 text-sm text-muted-foreground">trusted people</span></div><Link href="/safety" className="mt-6 flex items-center gap-2 text-sm font-semibold text-primary" data-testid="link-circle-card">Manage your circle <ChevronRight size={15} /></Link></Card>
      <Card className="p-6"><div className="flex items-center justify-between"><div><Eyebrow>gentle momentum</Eyebrow><h2 className="mt-2 font-display text-3xl">Small things count.</h2></div><Link href="/journal" className="text-sm font-semibold text-primary" data-testid="link-journal-card">Open journal <ArrowRight className="ml-1 inline" size={15} /></Link></div><div className="mt-6 grid gap-3 sm:grid-cols-2">{(d?.recentActivity ?? []).slice(0, 4).map((item: any) => <div key={item.id} className="flex gap-3 rounded-2xl bg-muted/60 p-3" data-testid={`activity-${item.id}`}><span className="mt-1 size-2 shrink-0 rounded-full bg-accent" /><div><p className="text-sm font-semibold">{item.title}</p><p className="mt-1 text-xs leading-5 text-muted-foreground">{item.detail}</p><p className="mt-2 font-mono-ui text-[9px] uppercase tracking-wider text-muted-foreground">{dateLabel(item.createdAt)}</p></div></div>)}{!d?.recentActivity?.length && <div className="sm:col-span-2"><EmptyState icon={Sparkles} title="A blank page can be kind." detail="Your recent check-ins and journal notes will appear here." action={<Button onClick={() => setLocation('/journal')} data-testid="button-start-journal">Write a note</Button>} /></div>}</div></Card>
    </div>
    <div className="grid gap-5 md:grid-cols-3"><Link href="/journal" className="group rounded-[24px] border border-border bg-[#cfddd6] p-5 transition hover:-translate-y-1" data-testid="link-quick-journal"><BookOpen className="text-primary" size={21} /><h3 className="mt-8 font-display text-2xl text-primary">A few words</h3><p className="mt-1 text-sm text-primary/65">Put it somewhere safe.</p><ArrowRight className="mt-5 text-primary transition group-hover:translate-x-1" size={17} /></Link><button onClick={() => checkin.mutate({ data: { durationMinutes: 30 } })} className="group rounded-[24px] border border-border bg-[#e9cfc0] p-5 text-left transition hover:-translate-y-1" data-testid="button-start-checkin"><Clock3 className="text-primary" size={21} /><h3 className="mt-8 font-display text-2xl text-primary">A timed check-in</h3><p className="mt-1 text-sm text-primary/65">{checkin.isPending ? 'Setting it up…' : 'A gentle nudge in 30 minutes.'}</p><ArrowRight className="mt-5 text-primary transition group-hover:translate-x-1" size={17} /></button><Link href="/support" className="group rounded-[24px] border border-border bg-secondary p-5 transition hover:-translate-y-1" data-testid="link-quick-support"><MessageCircle className="text-primary" size={21} /><h3 className="mt-8 font-display text-2xl text-primary">Talk it through</h3><p className="mt-1 text-sm text-primary/65">The companion is here.</p><ArrowRight className="mt-5 text-primary transition group-hover:translate-x-1" size={17} /></Link></div>
  </div>;
}

function Safety() {
  const qc = useQueryClient(); const contacts = useListTrustedContacts(); const journeys = useListJourneys(); const resources = useListSupportResources(); const createContact = useCreateTrustedContact(); const deleteContact = useDeleteTrustedContact(); const createJourney = useCreateJourney(); const updateJourney = useUpdateJourneyStatus(); const checkin = useCreateSafetyCheckin();
  const [showContact, setShowContact] = useState(false); const [showJourney, setShowJourney] = useState(false); const [form, setForm] = useState({ name: '', relationship: '', phone: '', email: '' }); const [journeyForm, setJourneyForm] = useState({ destination: '', expectedArrival: '' });
  const list = contacts.data ?? []; const journey = journeys.data?.[0];
  const refresh = () => { qc.invalidateQueries({ queryKey: getListTrustedContactsQueryKey() }); qc.invalidateQueries({ queryKey: getListJourneysQueryKey() }); };
  return <div className="animate-rise"><PageHeading eyebrow="your safety, your choices" title="A little more prepared." detail="Practical support for the moments you want a plan. Haven never tracks you in the background or sends messages without your action." action={<Link href="/emergency" className="inline-flex min-h-10 items-center justify-center gap-2 rounded-full bg-destructive px-4 text-sm font-semibold text-destructive-foreground transition hover:brightness-95" data-testid="link-open-emergency"><Zap size={16} />Emergency support</Link>} />
    <div className="grid gap-5 lg:grid-cols-[1.05fr_.95fr]">
      <Card className="overflow-hidden"><div className="flex items-center justify-between border-b border-border p-6"><div><Eyebrow>trusted circle</Eyebrow><h2 className="mt-2 font-display text-3xl">People you choose.</h2></div><Button variant="soft" className="size-10 p-0" onClick={() => setShowContact(true)} data-testid="button-add-contact"><Plus size={18} /></Button></div><div className="p-6">{contacts.isLoading ? <LoadingState /> : list.length === 0 ? <EmptyState icon={UsersRound} title="Make a circle." detail="Add someone you trust. They will only be contacted when you choose to share a journey or reach out." action={<Button variant="soft" onClick={() => setShowContact(true)} data-testid="button-empty-add-contact">Add someone</Button>} /> : <div className="space-y-3">{list.map((c: any) => <div key={c.id} className="flex items-center gap-3 rounded-2xl bg-muted/55 p-3" data-testid={`contact-${c.id}`}><span className="grid size-10 shrink-0 place-items-center rounded-full bg-primary text-sm font-semibold text-primary-foreground">{c.name.slice(0, 1).toUpperCase()}</span><div className="min-w-0 flex-1"><p className="truncate text-sm font-semibold">{c.name}</p><p className="text-xs text-muted-foreground">{c.relationship} · {c.phone}</p></div>{c.isEmergencyContact && <span className="rounded-full bg-secondary px-2 py-1 font-mono-ui text-[9px] uppercase tracking-widest text-primary">primary</span>}<button className="rounded-full p-2 text-muted-foreground hover:bg-background hover:text-destructive" onClick={() => { if (window.confirm(`Remove ${c.name} from your circle?`)) deleteContact.mutate({ id: c.id }, { onSuccess: refresh }); }} data-testid={`button-delete-contact-${c.id}`}><Trash2 size={15} /></button></div>)}</div>}</div></Card>
      <Card className="bg-[#cfddd6] p-6 text-primary"><div className="flex items-center justify-between"><span className="grid size-11 place-items-center rounded-2xl bg-[#e5eee9]"><Navigation size={20} /></span><span className="rounded-full bg-primary/10 px-3 py-1 font-mono-ui text-[10px] uppercase tracking-widest">journey mode</span></div><h2 className="mt-9 font-display text-4xl leading-none">{journey?.destination ?? 'Know your way home.'}</h2><p className="mt-3 max-w-sm text-sm leading-6 text-primary/65">{journey ? `Your plan is ${journey.status}. Sharing is ${journey.sharingStatus}.` : 'Set a destination and arrival time. You decide if a trusted person sees it.'}</p>{journey ? <div className="mt-7 flex flex-wrap gap-2"><Button onClick={() => updateJourney.mutate({ id: journey.id, data: { status: journey.status === 'active' ? 'arrived' : 'active' } }, { onSuccess: refresh })} data-testid="button-toggle-journey">{journey.status === 'active' ? 'Mark arrived' : 'Start again'}</Button><Button variant="quiet" className="border border-primary/15" onClick={() => updateJourney.mutate({ id: journey.id, data: { status: 'cancelled' } }, { onSuccess: refresh })} data-testid="button-cancel-journey">Cancel</Button></div> : <Button className="mt-7" onClick={() => setShowJourney(true)} data-testid="button-start-journey">Plan a journey <ArrowRight size={15} /></Button>}<p className="mt-6 flex items-center gap-2 text-xs text-primary/55"><LockKeyhole size={13} />No background tracking. Sharing is explicit.</p></Card>
    </div>
    <div className="mt-5 grid gap-5 md:grid-cols-3"><Card className="p-6"><span className="grid size-10 place-items-center rounded-2xl bg-secondary text-primary"><Clock3 size={19} /></span><h3 className="mt-8 font-display text-2xl">Safety check-in</h3><p className="mt-2 text-sm leading-6 text-muted-foreground">Set a one-time reminder to pause and check on yourself.</p><Button variant="soft" className="mt-6 w-full" onClick={() => checkin.mutate({ data: { durationMinutes: 30 } })} disabled={checkin.isPending} data-testid="button-safety-checkin">{checkin.isPending ? 'Setting up…' : 'Set for 30 minutes'}</Button></Card><Card className="p-6"><span className="grid size-10 place-items-center rounded-2xl bg-[#e9cfc0] text-primary"><Shield size={19} /></span><h3 className="mt-8 font-display text-2xl">A safety plan</h3><p className="mt-2 text-sm leading-6 text-muted-foreground">A private list of places, people, and steps that help you feel more ready.</p><Button variant="soft" className="mt-6 w-full" onClick={() => alert('Safety plan workspace is ready for your notes.')} data-testid="button-safety-plan">Open plan</Button></Card><Card className="p-6"><span className="grid size-10 place-items-center rounded-2xl bg-[#e6d7bd] text-primary"><LockKeyhole size={19} /></span><h3 className="mt-8 font-display text-2xl">Digital safety</h3><p className="mt-2 text-sm leading-6 text-muted-foreground">Small ways to protect your accounts, devices, and privacy.</p><Button variant="soft" className="mt-6 w-full" onClick={() => alert('Digital safety guide coming from your local resources.')} data-testid="button-digital-safety">Read guide</Button></Card></div>
    <Card className="mt-5 p-6"><div className="flex items-center justify-between"><div><Eyebrow>resource shelf</Eyebrow><h2 className="mt-2 font-display text-3xl">Keep useful numbers close.</h2></div><Link href="/support" className="text-sm font-semibold text-primary" data-testid="link-support-resources">View all <ArrowRight className="ml-1 inline" size={15} /></Link></div><div className="mt-5 flex gap-3 overflow-x-auto pb-1">{(resources.data ?? []).slice(0, 3).map((r: any) => <div key={r.id} className="min-w-[220px] rounded-2xl bg-muted/55 p-4"><p className="text-sm font-semibold">{r.name}</p><p className="mt-1 line-clamp-2 text-xs leading-5 text-muted-foreground">{r.description}</p><p className="mt-3 font-mono-ui text-[9px] uppercase tracking-widest text-primary">{r.isDemo ? 'Demo resource' : r.category}</p></div>)}{!resources.data?.length && <p className="text-sm text-muted-foreground">Resources are unavailable until your provider connects them.</p>}</div></Card>
    {showContact && <Modal title="Add to your circle" onClose={() => setShowContact(false)}><form className="space-y-4" onSubmit={e => { e.preventDefault(); createContact.mutate({ data: { ...form, isEmergencyContact: list.length === 0 } }, { onSuccess: () => { setShowContact(false); setForm({ name: '', relationship: '', phone: '', email: '' }); refresh(); } }); }}><Field label="Name" value={form.name} onChange={e => setForm({ ...form, name: e.target.value })} required data-testid="input-contact-name" /><Field label="Relationship" value={form.relationship} onChange={e => setForm({ ...form, relationship: e.target.value })} placeholder="Sister, friend, neighbor…" required data-testid="input-contact-relationship" /><Field label="Phone" value={form.phone} onChange={e => setForm({ ...form, phone: e.target.value })} required data-testid="input-contact-phone" /><Field label="Email (optional)" value={form.email} onChange={e => setForm({ ...form, email: e.target.value })} type="email" data-testid="input-contact-email" /><Button className="w-full" disabled={createContact.isPending} data-testid="button-save-contact">{createContact.isPending ? 'Saving…' : 'Save contact'}</Button></form></Modal>}
    {showJourney && <Modal title="Plan a journey" onClose={() => setShowJourney(false)}><form className="space-y-4" onSubmit={e => { e.preventDefault(); createJourney.mutate({ data: { destination: journeyForm.destination, expectedArrival: new Date(journeyForm.expectedArrival).toISOString(), contactIds: list.filter((c: any) => c.isEmergencyContact).map((c: any) => c.id) } }, { onSuccess: () => { setShowJourney(false); refresh(); } }); }}><Field label="Where are you going?" value={journeyForm.destination} onChange={e => setJourneyForm({ ...journeyForm, destination: e.target.value })} placeholder="A place or neighborhood" required data-testid="input-journey-destination" /><Field label="Expected arrival" type="datetime-local" value={journeyForm.expectedArrival} onChange={e => setJourneyForm({ ...journeyForm, expectedArrival: e.target.value })} required data-testid="input-journey-arrival" /><p className="text-xs leading-5 text-muted-foreground">Haven will not access your location. This plan only shares with contacts when you choose.</p><Button className="w-full" disabled={createJourney.isPending} data-testid="button-save-journey">{createJourney.isPending ? 'Starting…' : 'Start journey'}</Button></form></Modal>}
  </div>;
}

function Modal({ title, children, onClose }: { title: string; children: ReactNode; onClose: () => void }) { return <div className="fixed inset-0 z-50 grid place-items-center bg-primary/25 p-4 backdrop-blur-sm"><div className="w-full max-w-md rounded-[26px] border border-border bg-card p-6 shadow-lg animate-rise"><div className="flex items-center justify-between"><h2 className="font-display text-3xl text-primary">{title}</h2><button onClick={onClose} className="rounded-full p-2 hover:bg-muted" data-testid="button-close-modal"><X size={18} /></button></div><div className="mt-6">{children}</div></div></div>; }

function Journal() {
  const qc = useQueryClient(); const entries = useListJournalEntries(); const create = useCreateJournalEntry(); const update = useUpdateJournalEntry(); const remove = useDeleteJournalEntry();
  const [search, setSearch] = useState(''); const [editing, setEditing] = useState<any | null>(null); const [showForm, setShowForm] = useState(false); const [view, setView] = useState<'entries' | 'rhythm'>('entries'); const [form, setForm] = useState({ title: '', content: '', mood: 'calm', tags: '' });
  const list = useMemo(() => (entries.data ?? []).filter((e: any) => `${e.title} ${e.content} ${(e.tags ?? []).join(' ')}`.toLowerCase().includes(search.toLowerCase())), [entries.data, search]);
  const reset = () => { setShowForm(false); setEditing(null); setForm({ title: '', content: '', mood: 'calm', tags: '' }); };
  const save = (e: any) => { e.preventDefault(); const data = { title: form.title, content: form.content, mood: form.mood as any, tags: form.tags.split(',').map(t => t.trim()).filter(Boolean) }; if (editing) update.mutate({ id: editing.id, data }, { onSuccess: () => { reset(); qc.invalidateQueries({ queryKey: getListJournalEntriesQueryKey() }); } }); else create.mutate({ data }, { onSuccess: () => { reset(); qc.invalidateQueries({ queryKey: getListJournalEntriesQueryKey() }); } }); };
  return <div className="animate-rise"><PageHeading eyebrow="private, just for you" title="Your journal." detail="A place to notice patterns, hold a thought, or say the thing you did not say out loud." action={<Button onClick={() => setShowForm(true)} data-testid="button-new-entry"><Plus size={16} />New entry</Button>} />
    <div className="mb-5 flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between"><label className="relative block flex-1 sm:max-w-sm"><Search className="absolute left-3 top-3 text-muted-foreground" size={17} /><input type="search" value={search} onChange={e => setSearch(e.target.value)} placeholder="Search your notes" className="h-11 w-full rounded-full border border-input bg-card pl-10 pr-4 text-sm outline-none focus:border-primary" data-testid="input-journal-search" /></label><div className="flex rounded-full border border-border bg-card p-1"><button onClick={() => setView('entries')} className={`rounded-full px-4 py-2 text-xs font-semibold ${view === 'entries' ? 'bg-primary text-primary-foreground' : 'text-muted-foreground'}`} data-testid="button-view-entries">Entries</button><button onClick={() => setView('rhythm')} className={`rounded-full px-4 py-2 text-xs font-semibold ${view === 'rhythm' ? 'bg-primary text-primary-foreground' : 'text-muted-foreground'}`} data-testid="button-view-rhythm">Your rhythm</button></div></div>
    {entries.isLoading ? <LoadingState label="Opening your journal…" /> : entries.isError ? <ErrorState retry={() => entries.refetch()} /> : view === 'rhythm' ? <Rhythm entries={entries.data ?? []} /> : list.length === 0 ? <EmptyState icon={BookOpen} title={search ? 'Nothing matched.' : 'The page is yours.'} detail={search ? 'Try a different word or clear the search.' : 'Start with one honest sentence. It does not need to be polished.'} action={!search && <Button onClick={() => setShowForm(true)} data-testid="button-empty-new-entry">Write your first note</Button>} /> : <div className="grid gap-4 md:grid-cols-2">{list.map((entry: any, index: number) => <Card key={entry.id} className={`group p-5 transition hover:-translate-y-0.5 ${index === 0 ? 'md:col-span-2 md:p-7' : ''}`} data-testid={`journal-entry-${entry.id}`}><div className="flex items-start justify-between gap-4"><div className="flex items-center gap-2"><span className={`size-2.5 rounded-full ${moodDots[entry.mood] ?? 'bg-accent'}`} /><span className="font-mono-ui text-[10px] uppercase tracking-widest text-muted-foreground">{moodLabels[entry.mood] ?? entry.mood} · {dateLabel(entry.createdAt)}</span></div><div className="flex gap-1 opacity-0 transition group-hover:opacity-100"><button className="rounded-full p-2 hover:bg-muted" onClick={() => { setEditing(entry); setForm({ title: entry.title, content: entry.content, mood: entry.mood, tags: (entry.tags ?? []).join(', ') }); setShowForm(true); }} data-testid={`button-edit-entry-${entry.id}`}><Pencil size={15} /></button><button className="rounded-full p-2 hover:bg-muted" onClick={() => { if (window.confirm('Delete this journal entry?')) remove.mutate({ id: entry.id }, { onSuccess: () => qc.invalidateQueries({ queryKey: getListJournalEntriesQueryKey() }) }); }} data-testid={`button-delete-entry-${entry.id}`}><Trash2 size={15} /></button></div></div><h2 className={`mt-5 font-display text-3xl leading-none text-primary ${index === 0 ? 'md:text-4xl' : ''}`}>{entry.title}</h2><p className="mt-3 line-clamp-3 max-w-3xl text-sm leading-6 text-muted-foreground">{entry.content}</p><div className="mt-5 flex items-center gap-2">{(entry.tags ?? []).map((tag: string) => <span key={tag} className="rounded-full bg-muted px-2.5 py-1 text-[11px] text-muted-foreground">#{tag}</span>)}<button className={`ml-auto rounded-full p-2 ${entry.isFavorite ? 'text-secondary' : 'text-muted-foreground'}`} onClick={() => update.mutate({ id: entry.id, data: { isFavorite: !entry.isFavorite } }, { onSuccess: () => qc.invalidateQueries({ queryKey: getListJournalEntriesQueryKey() }) })} data-testid={`button-favorite-entry-${entry.id}`}><Star size={16} fill={entry.isFavorite ? 'currentColor' : 'none'} /></button></div></Card>)}</div>}
    {showForm && <Modal title={editing ? 'Edit your note' : 'A new page'} onClose={reset}><form className="space-y-4" onSubmit={save}><Field label="Title" value={form.title} onChange={e => setForm({ ...form, title: e.target.value })} placeholder="What is here?" required data-testid="input-entry-title" /><Textarea label="Your words" value={form.content} onChange={e => setForm({ ...form, content: e.target.value })} placeholder="No one else needs to read this." required data-testid="input-entry-content" /><div><p className="text-sm font-semibold">How does it feel?</p><div className="mt-2 flex flex-wrap gap-2">{Object.entries(moodLabels).map(([value, label]) => <button type="button" key={value} onClick={() => setForm({ ...form, mood: value })} className={`rounded-full border px-3 py-2 text-xs ${form.mood === value ? 'border-primary bg-primary text-primary-foreground' : 'border-border bg-background'}`} data-testid={`button-entry-mood-${value}`}>{label}</button>)}</div></div><Field label="Tags" value={form.tags} onChange={e => setForm({ ...form, tags: e.target.value })} placeholder="work, home, reflection" data-testid="input-entry-tags" /><Button className="w-full" disabled={create.isPending || update.isPending} data-testid="button-save-entry">{create.isPending || update.isPending ? 'Saving…' : 'Save privately'}</Button></form></Modal>}
  </div>;
}
function Rhythm({ entries }: { entries: any[] }) { const moods = entries.reduce((a: any, e: any) => { a[e.mood] = (a[e.mood] || 0) + 1; return a; }, {}); return <div className="grid gap-5 lg:grid-cols-[1.1fr_.9fr]"><Card className="p-6"><div className="flex items-center justify-between"><div><Eyebrow>last 30 days</Eyebrow><h2 className="mt-2 font-display text-3xl">A gentle look back.</h2></div><CalendarDays className="text-accent" /></div><div className="mt-8 grid grid-cols-7 gap-2">{Array.from({ length: 35 }).map((_, i) => <span key={i} className={`aspect-square rounded-md ${i > 28 ? 'bg-muted/30' : i % 8 === 0 ? 'bg-accent' : i % 5 === 0 ? 'bg-secondary' : i % 3 === 0 ? 'bg-primary/60' : 'bg-muted'}`} />)}</div><p className="mt-5 text-xs leading-5 text-muted-foreground">This is a reflection aid, not a diagnosis. Your entries stay yours.</p></Card><Card className="p-6"><Eyebrow>what is showing up</Eyebrow><h2 className="mt-2 font-display text-3xl">Your words, in color.</h2><div className="mt-7 space-y-4">{Object.entries(moods).length ? Object.entries(moods).map(([mood, count]: any) => <div key={mood}><div className="flex justify-between text-sm"><span>{moodLabels[mood] ?? mood}</span><span className="font-mono-ui text-xs text-muted-foreground">{count} {count === 1 ? 'note' : 'notes'}</span></div><div className="mt-2 h-2 overflow-hidden rounded-full bg-muted"><div className={`h-full rounded-full ${moodDots[mood]}`} style={{ width: `${Math.min(100, count / entries.length * 100 + 15)}%` }} /></div></div>) : <p className="text-sm text-muted-foreground">Your pattern will appear after a few notes.</p>}</div></Card></div>; }

function Support() {
  const resources = useListSupportResources(); const send = useSendCompanionMessage(); const [message, setMessage] = useState(''); const [chat, setChat] = useState<any[]>([{ id: 'welcome', role: 'companion', content: 'I am here to help you think through a next step. I am not a therapist, crisis service, or substitute for local emergency support. What is on your mind?', safetyLevel: 'normal' }]); const [category, setCategory] = useState('all');
  const submit = (e: any) => { e.preventDefault(); if (!message.trim()) return; const content = message.trim(); setMessage(''); setChat(c => [...c, { id: `${Date.now()}-u`, role: 'user', content }, { id: `${Date.now()}-p`, role: 'companion', content: 'Thank you for telling me. We can slow this down and look at the choices in front of you. If you may be in immediate danger, use Emergency support or contact local emergency services now.', safetyLevel: 'normal' }]); send.mutate({ data: { content } }); };
  const filtered = (resources.data ?? []).filter((r: any) => category === 'all' || r.category === category);
  return <div className="animate-rise"><PageHeading eyebrow="support without pressure" title="You do not have to hold it alone." detail="Start with a quiet conversation, find a practical resource, or use the emergency entry point when you need it." action={<Link href="/emergency" className="inline-flex min-h-10 items-center justify-center gap-2 rounded-full bg-destructive px-4 text-sm font-semibold text-destructive-foreground transition hover:brightness-95" data-testid="link-support-emergency"><Zap size={16} />I need urgent help</Link>} /><div className="grid gap-5 lg:grid-cols-[1.1fr_.9fr]"><Card className="flex min-h-[520px] flex-col overflow-hidden"><div className="border-b border-border bg-[#cfddd6] p-6"><div className="flex items-center gap-3"><span className="grid size-10 place-items-center rounded-2xl bg-[#e5eee9] text-primary"><Sparkles size={20} /></span><div><Eyebrow>haven companion</Eyebrow><h2 className="mt-1 font-display text-2xl text-primary">A calm second voice.</h2></div></div><p className="mt-4 text-xs leading-5 text-primary/65">Supportive reflection only. Not a therapist, medical provider, or emergency service.</p></div><div className="flex-1 space-y-4 overflow-auto p-5">{chat.map((m, i) => <div key={m.id} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'}`} data-testid={`chat-message-${i}`}><div className={`max-w-[84%] rounded-2xl px-4 py-3 text-sm leading-6 ${m.role === 'user' ? 'rounded-br-sm bg-primary text-primary-foreground' : 'rounded-bl-sm bg-muted text-foreground'}`}>{m.content}</div></div>)}</div><form onSubmit={submit} className="flex gap-2 border-t border-border p-4"><input value={message} onChange={e => setMessage(e.target.value)} placeholder="Write what is here…" className="h-11 min-w-0 flex-1 rounded-full border border-input bg-background px-4 text-sm outline-none focus:border-primary" data-testid="input-companion-message" /><Button className="size-11 shrink-0 p-0" disabled={send.isPending} data-testid="button-send-companion"><ArrowRight size={17} /></Button></form></Card><Card className="p-6"><div className="flex items-center justify-between"><div><Eyebrow>resource directory</Eyebrow><h2 className="mt-2 font-display text-3xl">Practical, local next steps.</h2></div><HeartHandshake className="text-accent" /></div><div className="mt-5 flex gap-2 overflow-auto pb-1">{['all','professional','legal','safety','emergency'].map(c => <button key={c} onClick={() => setCategory(c)} className={`whitespace-nowrap rounded-full px-3 py-2 text-xs font-semibold capitalize ${category === c ? 'bg-primary text-primary-foreground' : 'bg-muted text-muted-foreground'}`} data-testid={`button-filter-${c}`}>{c}</button>)}</div><div className="mt-5 space-y-3">{resources.isLoading ? <LoadingState label="Checking resource shelf…" /> : filtered.length ? filtered.map((r: any) => <div key={r.id} className="rounded-2xl border border-border bg-background p-4" data-testid={`resource-${r.id}`}><div className="flex items-start justify-between gap-3"><div><p className="text-sm font-semibold">{r.name}</p><p className="mt-1 text-xs leading-5 text-muted-foreground">{r.description}</p></div><span className="rounded-full bg-secondary/60 px-2 py-1 font-mono-ui text-[9px] uppercase tracking-wider text-primary">{r.isDemo ? 'Demo' : r.category}</span></div><div className="mt-3 flex gap-3 text-xs font-semibold text-primary">{r.phone && <a href={`tel:${r.phone}`} className="flex items-center gap-1" data-testid={`link-call-resource-${r.id}`}><Phone size={13} />Call</a>}{r.website && <a href={r.website} target="_blank" rel="noreferrer" className="flex items-center gap-1" data-testid={`link-resource-${r.id}`}><ExternalLink size={13} />Website</a>}</div></div>) : <EmptyState icon={HeartHandshake} title="No resources here yet." detail="Your provider has not configured this directory. You can still use your trusted circle or local emergency services." />}</div></Card></div></div>;
}

function Profile() { const [privateMode, setPrivateMode] = useState(true); const [notifications, setNotifications] = useState(true); return <div className="animate-rise"><PageHeading eyebrow="your haven" title="Preferences." detail="Make this space feel like yours. These choices live in this browser until your account settings are connected." /><div className="grid gap-5 lg:grid-cols-[.8fr_1.2fr]"><Card className="bg-primary p-7 text-primary-foreground"><span className="grid size-14 place-items-center rounded-[20px] bg-secondary text-primary"><UserRound size={25} /></span><h2 className="mt-7 font-display text-4xl">Your profile.</h2><p className="mt-2 text-sm text-primary-foreground/65">Private account · last synced recently</p><div className="mt-10 border-t border-primary-foreground/15 pt-5"><div className="flex items-center gap-2 text-secondary"><LockKeyhole size={15} /><span className="font-mono-ui text-[10px] uppercase tracking-widest">protected space</span></div><p className="mt-2 text-xs leading-5 text-primary-foreground/60">Haven is a companion, not a monitoring service. You are in control of every share.</p></div></Card><div className="space-y-5"><Card className="p-6"><Eyebrow>privacy</Eyebrow><h2 className="mt-2 font-display text-3xl">Your boundaries.</h2><SettingRow icon={LockKeyhole} title="Private mode" detail="Hide previews and keep your space quiet in shared moments." value={privateMode} onChange={() => setPrivateMode(!privateMode)} testId="switch-private-mode" /><SettingRow icon={MapPin} title="Location permissions" detail="Location is not connected. Journey mode uses only details you enter." value={false} onChange={() => alert('Location is not configured for Haven.')} testId="switch-location-permissions" disabled /><SettingRow icon={Bell} title="Gentle reminders" detail="Allow one-time check-in reminders you create." value={notifications} onChange={() => setNotifications(!notifications)} testId="switch-notifications" /></Card><Card className="p-6"><Eyebrow>your data</Eyebrow><h2 className="mt-2 font-display text-3xl">Take it with you.</h2><p className="mt-2 text-sm leading-6 text-muted-foreground">Export and deletion controls are shown here so the boundary is clear. Connect your account provider to make them active.</p><div className="mt-5 flex flex-wrap gap-2"><Button variant="soft" disabled data-testid="button-export-data"><Download size={15} />Export data</Button><Button variant="quiet" disabled data-testid="button-delete-data"><Trash2 size={15} />Delete account</Button></div></Card></div></div></div>; }
function SettingRow({ icon: Icon, title, detail, value, onChange, testId, disabled = false }: { icon: typeof LockKeyhole; title: string; detail: string; value: boolean; onChange: () => void; testId: string; disabled?: boolean }) { return <div className="mt-6 flex items-start gap-3 border-t border-border pt-5"><span className="mt-1 grid size-9 place-items-center rounded-xl bg-muted text-primary"><Icon size={16} /></span><div className="flex-1"><p className="text-sm font-semibold">{title}</p><p className="mt-1 max-w-md text-xs leading-5 text-muted-foreground">{detail}</p></div><button onClick={onChange} disabled={disabled} className={`relative mt-1 h-6 w-11 rounded-full transition ${value ? 'bg-primary' : 'bg-muted'} disabled:opacity-50`} data-testid={testId}><span className={`absolute top-1 size-4 rounded-full bg-card transition-all ${value ? 'left-6' : 'left-1'}`} /></button></div>; }

function Emergency() { const [status, setStatus] = useState<'ready' | 'active' | 'paused'>('ready'); const [permission, setPermission] = useState(false); const contacts = useListTrustedContacts(); return <div className="mx-auto max-w-3xl animate-rise"><div className="mb-8"><Link href="/" className="flex items-center gap-2 text-sm font-semibold text-primary" data-testid="link-back-home"><ChevronRight className="rotate-180" size={15} />Back to Haven</Link></div><Card className={`overflow-hidden ${status === 'active' ? 'border-accent' : ''}`}><div className={`p-7 md:p-12 ${status === 'active' ? 'bg-[#ead0c4]' : 'bg-primary'} ${status === 'active' ? 'text-primary' : 'text-primary-foreground'}`}><div className="flex items-center justify-between"><span className={`grid size-14 place-items-center rounded-[20px] ${status === 'active' ? 'bg-[#f5e4dc]' : 'bg-secondary text-primary'}`}><Zap size={25} /></span><span className={`font-mono-ui text-[10px] uppercase tracking-[.2em] ${status === 'active' ? 'text-primary/60' : 'text-primary-foreground/60'}`}>{status === 'ready' ? 'emergency entry point' : `support ${status}`}</span></div><h1 className="mt-10 font-display text-6xl leading-[.88] md:text-8xl">{status === 'active' ? 'You are<br /><i>not alone.</i>' : 'Make room<br /><i>for help.</i>'}</h1><p className={`mt-6 max-w-lg text-sm leading-6 ${status === 'active' ? 'text-primary/70' : 'text-primary-foreground/70'}`}>{status === 'active' ? 'This screen helps you take the next step. Haven does not dispatch emergency services or send automatic messages.' : 'If you are in immediate danger, call your local emergency number now. Haven can help you gather the choices you have configured.'}</p></div><div className="p-7 md:p-10">{status === 'ready' && <div className="space-y-5"><div className="rounded-2xl border border-border bg-muted/45 p-4"><div className="flex items-start gap-3"><MapPin className="mt-0.5 text-accent" size={19} /><div><p className="text-sm font-semibold">Location is not connected</p><p className="mt-1 text-xs leading-5 text-muted-foreground">Haven cannot access or share your location until you explicitly allow a configured provider. You can still open a map link yourself.</p><label className="mt-3 flex items-center gap-2 text-xs font-semibold"><input type="checkbox" checked={permission} onChange={e => setPermission(e.target.checked)} data-testid="checkbox-location-permission" />I understand and want to enable location for this session</label></div></div></div><Button variant="danger" className="h-14 w-full text-base" onClick={() => setStatus('active')} disabled={!permission} data-testid="button-activate-emergency"><Zap size={18} />Activate support screen</Button><a href="tel:911" className="flex h-12 items-center justify-center gap-2 rounded-full border border-border text-sm font-semibold text-primary" data-testid="link-call-emergency"><Phone size={16} />Call local emergency services</a></div>}{status === 'active' && <div className="space-y-5"><div className="flex items-center gap-3 rounded-2xl bg-muted/55 p-4"><span className="size-2.5 animate-pulse rounded-full bg-accent" /><div><p className="text-sm font-semibold">Session active on this screen</p><p className="text-xs text-muted-foreground">No message has been sent automatically.</p></div></div><div className="grid gap-3 sm:grid-cols-2"><a href="https://maps.google.com/?q=police+station" target="_blank" rel="noreferrer" className="flex items-center justify-center gap-2 rounded-2xl border border-border p-4 text-sm font-semibold" data-testid="link-open-map"><MapPin size={16} />Open map</a><button onClick={() => setStatus('paused')} className="flex items-center justify-center gap-2 rounded-2xl border border-border p-4 text-sm font-semibold" data-testid="button-pause-emergency"><Clock3 size={16} />Pause screen</button></div><div><Eyebrow>your circle</Eyebrow><div className="mt-3 space-y-2">{(contacts.data ?? []).map((c: any) => <a href={`tel:${c.phone}`} key={c.id} className="flex items-center gap-3 rounded-2xl bg-muted/55 p-3" data-testid={`link-emergency-contact-${c.id}`}><span className="grid size-9 place-items-center rounded-full bg-primary text-sm text-primary-foreground">{c.name.slice(0, 1)}</span><span className="flex-1 text-sm font-semibold">{c.name}</span><Phone size={15} className="text-primary" /></a>)}{!contacts.data?.length && <p className="text-sm text-muted-foreground">No trusted contacts configured yet.</p>}</div></div><Button variant="quiet" className="w-full border border-border" onClick={() => setStatus('ready')} data-testid="button-cancel-emergency">Close support screen</Button></div>}{status === 'paused' && <div className="text-center"><Clock3 className="mx-auto text-accent" size={30} /><h2 className="mt-4 font-display text-3xl">Paused for now.</h2><p className="mx-auto mt-2 max-w-sm text-sm leading-6 text-muted-foreground">Nothing is running in the background. Re-open the support screen whenever you choose.</p><Button className="mt-6" onClick={() => setStatus('active')} data-testid="button-resume-emergency">Resume screen</Button></div>}</div></Card><p className="mt-5 text-center text-xs leading-5 text-muted-foreground">Haven is not a replacement for emergency services, medical care, or professional legal advice.</p></div>; }

function Auth({ mode }: { mode: 'welcome' | 'login' | 'signup' | 'forgot' | 'onboarding' }) { const copy = { welcome: ['A softer place to land.', 'Private check-ins, practical support, and room to think.'], login: ['Welcome back.', 'Your quiet space is here.'], signup: ['Make a little room.', 'Set up a private space that follows your choices.'], forgot: ['Find your way back.', 'We will help you reset your access.'], onboarding: ['Let’s make this yours.', 'A few choices now, and Haven will meet you where you are.'] }[mode]; const [email, setEmail] = useState(''); return <div className="min-h-[100dvh] bg-[#e6d7bd] p-4 md:p-8"><div className="mx-auto flex min-h-[calc(100dvh-2rem)] max-w-6xl overflow-hidden rounded-[32px] border border-primary/10 bg-card shadow-lg md:min-h-[calc(100dvh-4rem)]"><div className="relative hidden w-[43%] overflow-hidden bg-primary p-10 text-primary-foreground md:block"><div className="absolute -right-24 top-24 size-80 rounded-full border border-secondary/20" /><div className="absolute -bottom-28 -left-24 size-96 rounded-full border border-secondary/20" /><Logo /><div className="absolute bottom-12 left-10 right-10"><span className="font-mono-ui text-[10px] uppercase tracking-widest text-secondary">a private companion</span><p className="mt-4 font-display text-6xl leading-[.88]">Keep close<br /><i>to yourself.</i></p><p className="mt-5 max-w-xs text-sm leading-6 text-primary-foreground/65">A quiet place for what you feel, what you know, and what you might need next.</p></div></div><div className="flex flex-1 flex-col p-6 md:p-14"><div className="md:hidden"><Logo /></div><div className="mx-auto flex w-full max-w-md flex-1 flex-col justify-center"><Eyebrow>{mode === 'onboarding' ? 'getting started' : 'haven'}</Eyebrow><h1 className="mt-3 font-display text-5xl leading-[.9] text-primary">{copy[0]}</h1><p className="mt-4 text-sm leading-6 text-muted-foreground">{copy[1]}</p>{mode === 'welcome' && <div className="mt-10 space-y-3"><Link href="/signup" className="flex h-12 items-center justify-between rounded-full bg-primary px-5 text-sm font-semibold text-primary-foreground" data-testid="link-welcome-signup">Create private space <ArrowRight size={17} /></Link><Link href="/login" className="flex h-12 items-center justify-center rounded-full border border-border text-sm font-semibold text-primary" data-testid="link-welcome-login">I already have a space</Link></div>}{mode !== 'welcome' && mode !== 'onboarding' && <form className="mt-9 space-y-4" onSubmit={e => e.preventDefault()}><Field label="Email" type="email" value={email} onChange={e => setEmail(e.target.value)} required data-testid="input-auth-email" />{mode !== 'forgot' && <Field label="Password" type="password" placeholder="At least 8 characters" required data-testid="input-auth-password" />}<Button className="h-12 w-full" data-testid="button-auth-submit">{mode === 'forgot' ? 'Send reset link' : mode === 'signup' ? 'Create my space' : 'Continue'}</Button></form>}{mode === 'onboarding' && <div className="mt-9 space-y-4"><label className="block text-sm font-semibold">What would feel most useful first?<select className="mt-2 h-12 w-full rounded-xl border border-input bg-background px-3 text-sm font-normal" data-testid="select-onboarding-focus"><option>Private check-ins</option><option>A journal for my thoughts</option><option>Trusted contacts and journeys</option></select></label><Link href="/" className="flex h-12 w-full items-center justify-center rounded-full bg-primary text-sm font-semibold text-primary-foreground" data-testid="link-finish-onboarding">Enter Haven <ArrowRight className="ml-2" size={17} /></Link></div>}{mode === 'login' && <Link href="/forgot-password" className="mt-4 block text-center text-xs font-semibold text-primary" data-testid="link-forgot-password">Forgot your password?</Link>}{mode !== 'onboarding' && <p className="mt-8 text-center text-xs text-muted-foreground">{mode === 'login' ? 'New here? ' : 'Already have a space? '}<Link href={mode === 'login' ? '/signup' : '/login'} className="font-semibold text-primary" data-testid="link-auth-switch">{mode === 'login' ? 'Create one' : 'Sign in'}</Link></p>}</div></div></div></div>; }

function Router() { const [location] = useLocation(); const auth = ['/welcome', '/login', '/signup', '/forgot-password', '/onboarding'].includes(location); return auth ? <Switch><Route path="/welcome"><Auth mode="welcome" /></Route><Route path="/login"><Auth mode="login" /></Route><Route path="/signup"><Auth mode="signup" /></Route><Route path="/forgot-password"><Auth mode="forgot" /></Route><Route path="/onboarding"><Auth mode="onboarding" /></Route><Route component={NotFound} /></Switch> : <Shell><Switch><Route path="/" component={Dashboard} /><Route path="/safety" component={Safety} /><Route path="/journal" component={Journal} /><Route path="/support" component={Support} /><Route path="/profile" component={Profile} /><Route path="/emergency" component={Emergency} /><Route component={NotFound} /></Switch></Shell>; }
function App() { return <QueryClientProvider client={queryClient}><TooltipProvider><Router /><Toaster /></TooltipProvider></QueryClientProvider>; }
export default App;